function yearOf(p){const match=p.venue.match(/\b(20\d{2})\b/);return match?Number(match[1]):null;}
function newestFirst(items,key=p=>p){return items.slice().sort((a,b)=>(yearOf(key(b))||0)-(yearOf(key(a))||0));}
function yearGroups(container,items,render,options={}){
 container.className='year-collection';
 const groups=new Map();
 newestFirst(items,options.paper||((p)=>p)).forEach(item=>{const p=options.paper?options.paper(item):item;const year=yearOf(p);const label=year===null?(options.undated||'Undated work'):String(year)+(options.suffix||'');if(!groups.has(label))groups.set(label,[]);groups.get(label).push(item);});
 groups.forEach((entries,label)=>{const section=el('section',null,'year-group');section.setAttribute('data-year-group',label);section.append(el('h2',label,'year-heading'));const content=el('div',null,options.grid?'grid':'year-entries');entries.forEach(item=>content.append(render(item)));section.append(content);container.append(section);});
}
